import React, { useState, useContext } from 'react';
import { useNavigate } from 'react-router-dom';
import { AuthContext } from '../context/AuthContext';

const Login = () => {
  const [email, setEmail] = useState('');
  const [password, setPassword] = useState('');
  const { login } = useContext(AuthContext);
  const navigate = useNavigate();

  const handleSubmit = (e) => {
    e.preventDefault();
    // Simulation en attendant le backend réel
    login({ email, role: email.includes('admin') ? 'admin' : 'student' });
    navigate('/dashboard');
  };

  return (
    <div className="min-h-screen bg-[#020617] flex items-center justify-center p-4">
      <div className="w-full max-w-sm bg-slate-950 border border-slate-900 p-8 rounded-xl shadow-2xl">
        <h2 className="text-white font-bold text-lg mb-6 uppercase text-center">Connexion</h2>
        <form onSubmit={handleSubmit} className="space-y-4">
          <input
            type="email"
            placeholder="Email"
            onChange={(e) => setEmail(e.target.value)}
            className="w-full bg-slate-900 border border-slate-800 text-white px-4 py-2 rounded focus:outline-none focus:border-blue-500"
          />
          <input
            type="password"
            placeholder="Mot de passe"
            onChange={(e) => setPassword(e.target.value)}
            className="w-full bg-slate-900 border border-slate-800 text-white px-4 py-2 rounded focus:outline-none focus:border-blue-500"
          />
          <button type="submit" className="w-full bg-blue-600 text-white py-2 rounded font-bold uppercase hover:bg-blue-500 transition">
            Valider
          </button>
        </form>
      </div>
    </div>
  );
};
export default Login;
